revoke all on function public.place_order(text,text,jsonb) from anon,authenticated,public;
revoke all on function public.rls_auto_enable() from anon,authenticated,public;
drop policy if exists "No direct public access to orders" on public.orders;
drop policy if exists "No direct public access to order items" on public.order_items;
-- RLS policies intentionally use (select auth.jwt()) so the JWT is evaluated once per statement rather than per row.
drop policy if exists "Admins can read own admin record" on public.admins;
create policy "Admins can read own admin record" on public.admins for select to authenticated using(lower(email)=lower(coalesce((select auth.jwt()->>'email'),'')));
drop policy if exists "Public can read active products" on public.products;
create policy "Public can read active products" on public.products for select to anon,authenticated using(active=true or exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can insert products" on public.products;
create policy "Admins can insert products" on public.products for insert to authenticated with check(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can update products" on public.products;
create policy "Admins can update products" on public.products for update to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),'')))) with check(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can delete products" on public.products;
create policy "Admins can delete products" on public.products for delete to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
