drop policy if exists "Admins can delete categories" on public.menu_categories;
create policy "Admins can delete categories" on public.menu_categories for delete to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
